before:
Complete local C example; the app itself does not execute it:
```c
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>

int main(void) {
 size_t count = 3;
 size_t width = sizeof(int);
 if (count == 0 || count > SIZE_MAX / width) {
  puts("rejected"); return 0;
 }
 int *a = malloc(count * width);
 if (a == NULL) { return 1; }
 a[0] = 7;
 printf("%d\n", a[0]);
 free(a);
}
```

